#!/usr/bin/env python3
"""
Generate 15 Perlin-noise landscape gradients using a coral palette.
Color thresholds are mapped via harmonic music interval ratios.
Each landscape uses a different musical structure to partition the noise field.
"""

import json
import math
import random
from pathlib import Path

random.seed(42)

# ── Coral Palette (full dynamic range from sea anemone photo) ─
# Deep darks for contrast + vivid corals + bright highlights
PALETTE = [
    [8,    2,   3],      # 0  abyss black
    [28,   6,   5],      # 1  deep void
    [52,  10,   8],      # 2  dark maroon
    [80,  16,  12],      # 3  maroon
    [110, 22,  18],      # 4  dark crimson
    [139, 26,  24],      # 5  crimson
    [165, 34,  28],      # 6  blood red
    [181, 42,  32],      # 7  deep red
    [200, 50,  32],      # 8  red
    [212, 56,  32],      # 9  vermillion
    [225, 65,  36],      # 10 bright vermillion
    [232, 72,  40],      # 11 red-orange
    [240, 96,  48],      # 12 orange
    [248, 128, 80],      # 13 light orange
    [255, 155, 110],     # 14 coral
    [255, 175, 140],     # 15 salmon
    [255, 200, 175],     # 16 peach
    [255, 225, 210],     # 17 blush
    [255, 240, 228],     # 18 pink white
    [255, 248, 242],     # 19 shell white
    [255, 252, 250],     # 20 near white
]


def norm(ratios):
    """Normalize frequency ratios to [0,1] thresholds."""
    lo, hi = ratios[0], ratios[-1]
    return [round((r - lo) / (hi - lo), 4) for r in ratios]


TEMPLATE = r"""<!DOCTYPE html>
<html lang="en"><head><meta charset="UTF-8">
<title>{{TITLE}}</title>
<style>*{margin:0;padding:0}body{background:#1a1a2e;display:flex;align-items:center;justify-content:center;min-height:100vh}
canvas{display:block;image-rendering:pixelated}</style>
</head><body>
<canvas id="c"></canvas>
<script>
// Perlin noise implementation (improved)
const P=new Uint8Array(512);
(function(){const p=[{{PERM}}];for(let i=0;i<512;i++)P[i]=p[i&255]})();
function fade(t){return t*t*t*(t*(t*6-15)+10)}
function lerp(a,b,t){return a+t*(b-a)}
function grad(h,x,y){const v=h&3;return((v&1)?-x:x)+((v&2)?-y:y)}
function perlin(x,y){
  const X=Math.floor(x)&255,Y=Math.floor(y)&255;
  x-=Math.floor(x);y-=Math.floor(y);
  const u=fade(x),v=fade(y);
  const A=P[X]+Y,B=P[X+1]+Y;
  return lerp(lerp(grad(P[A],x,y),grad(P[B],x-1,y),u),
              lerp(grad(P[A+1],x,y-1),grad(P[B+1],x-1,y-1),u),v);
}

// Fractal Brownian Motion
function fbm(x,y,octaves,lacunarity,gain){
  let val=0,amp=1,freq=1,max=0;
  for(let i=0;i<octaves;i++){val+=amp*perlin(x*freq,y*freq);max+=amp;amp*=gain;freq*=lacunarity;}
  return val/max;
}

// Domain warping for organic shapes
function warp(x,y,oct,lac,gain,warpAmt){
  const q0=fbm(x,y,oct,lac,gain);
  const q1=fbm(x+5.2,y+1.3,oct,lac,gain);
  return fbm(x+warpAmt*q0,y+warpAmt*q1,oct,lac,gain);
}

// Ridge noise for mountain-like features
function ridge(x,y,octaves,lacunarity,gain){
  let val=0,amp=1,freq=1,max=0,prev=1;
  for(let i=0;i<octaves;i++){
    let n=Math.abs(perlin(x*freq,y*freq));
    n=prev-n; n=n*n;
    val+=n*amp; max+=amp; prev=n;
    amp*=gain; freq*=lacunarity;
  }
  return val/max;
}

const W={{WIDTH}},H={{HEIGHT}};
const canvas=document.getElementById('c');
canvas.width=W;canvas.height=H;
const ctx=canvas.getContext('2d');
const img=ctx.createImageData(W,H);

// Palette & harmonic thresholds
const palette={{PALETTE_JSON}};
const thresholds={{THRESHOLDS_JSON}};
const colorIndices={{COLOR_INDICES_JSON}};

// Noise config
const cfg={{NOISE_CFG}};

for(let y=0;y<H;y++){
  for(let x=0;x<W;x++){
    const nx=x/W*cfg.scale+cfg.offsetX;
    const ny=y/H*cfg.scale+cfg.offsetY;

    let n;
    if(cfg.mode==='warp'){
      n=warp(nx,ny,cfg.octaves,cfg.lacunarity,cfg.gain,cfg.warpAmt);
    } else if(cfg.mode==='ridge'){
      n=ridge(nx,ny,cfg.octaves,cfg.lacunarity,cfg.gain);
    } else if(cfg.mode==='turbulence'){
      n=Math.abs(fbm(nx,ny,cfg.octaves,cfg.lacunarity,cfg.gain));
    } else if(cfg.mode==='terraced'){
      n=fbm(nx,ny,cfg.octaves,cfg.lacunarity,cfg.gain);
      n=(n+1)*0.5;
      const steps=cfg.terraceSteps||8;
      n=Math.floor(n*steps)/steps;
    } else {
      n=fbm(nx,ny,cfg.octaves,cfg.lacunarity,cfg.gain);
    }

    // Apply vertical gradient bias if configured
    if(cfg.vBias){
      n+=cfg.vBias*(y/H-0.5)*2;
    }

    // Normalize to [0,1]
    n=(n+1)*0.5;
    n=Math.max(0,Math.min(1,n));

    // Apply contrast/gamma
    if(cfg.gamma) n=Math.pow(n,cfg.gamma);

    // Map noise to palette via harmonic thresholds
    let ci=0;
    for(let t=1;t<thresholds.length;t++){
      if(n>=thresholds[t]) ci=t;
    }

    // Smooth interpolation between adjacent colors
    let lo=thresholds[ci], hi=(ci<thresholds.length-1)?thresholds[ci+1]:1;
    let frac=(hi>lo)?Math.min(1,(n-lo)/(hi-lo)):0;
    const c0=palette[colorIndices[ci]];
    const c1=palette[colorIndices[Math.min(ci+1,colorIndices.length-1)]];

    const idx=(y*W+x)*4;
    img.data[idx  ]=Math.round(c0[0]+(c1[0]-c0[0])*frac);
    img.data[idx+1]=Math.round(c0[1]+(c1[1]-c0[1])*frac);
    img.data[idx+2]=Math.round(c0[2]+(c1[2]-c0[2])*frac);
    img.data[idx+3]=255;
  }
}
ctx.putImageData(img,0,0);
</script></body></html>"""


def make_perm():
    """Generate a random permutation table for Perlin noise."""
    p = list(range(256))
    random.shuffle(p)
    return ','.join(str(x) for x in p)


def generate(name, title, width, height, color_indices, ratios, noise_cfg):
    """Generate one landscape HTML file."""
    thresholds = norm(ratios)
    html = TEMPLATE
    html = html.replace('{{TITLE}}', title)
    html = html.replace('{{WIDTH}}', str(width))
    html = html.replace('{{HEIGHT}}', str(height))
    html = html.replace('{{PERM}}', make_perm())
    html = html.replace('{{PALETTE_JSON}}', json.dumps(PALETTE))
    html = html.replace('{{THRESHOLDS_JSON}}', json.dumps(thresholds))
    html = html.replace('{{COLOR_INDICES_JSON}}', json.dumps(color_indices))
    html = html.replace('{{NOISE_CFG}}', json.dumps(noise_cfg))

    out = Path('gradients') / f'{name}.html'
    out.parent.mkdir(exist_ok=True)
    out.write_text(html)
    print(f'  {name}.html  ({width}x{height}, {noise_cfg["mode"]}, {len(color_indices)} colors)')


# ═══════════════════════════════════════════════════════════════
print('Generating 15 Perlin noise + harmonic coral landscapes...\n')

# All use plain fbm with very low octaves (1-2) for ultra-smooth gradient feel.
# No domain warping. Large scale. Subtle directional biases.

# 1. OCTAVE (1:2) — Smooth diagonal wash
generate('01_octave', 'Octave — Smooth Wash', 800, 500,
    [6, 10, 14, 18],
    [1, 4/3, 5/3, 2],
    {'mode': 'fbm', 'scale': 1.5, 'octaves': 2, 'lacunarity': 2.0,
     'gain': 0.3, 'offsetX': 0.0, 'offsetY': 0.0, 'gamma': 1.0})

# 2. PERFECT FIFTH (2:3) — Gentle vertical gradient
generate('02_perfect_fifth', 'Perfect Fifth — Gentle Fade', 800, 500,
    [4, 7, 10, 13, 16, 19],
    [1, 9/8, 5/4, 3/2, 5/3, 2],
    {'mode': 'fbm', 'scale': 1.2, 'octaves': 1, 'lacunarity': 2.0,
     'gain': 0.3, 'offsetX': 1.7, 'offsetY': 3.2,
     'vBias': 0.4, 'gamma': 1.0})

# 3. MAJOR TRIAD (4:5:6) — Soft warm horizon
generate('03_major_triad', 'Major Triad — Warm Horizon', 800, 500,
    [5, 8, 11, 14, 17, 20],
    [4, 4.4, 4.8, 5.3, 5.7, 6],
    {'mode': 'fbm', 'scale': 1.8, 'octaves': 2, 'lacunarity': 2.0,
     'gain': 0.3, 'offsetX': 7.3, 'offsetY': 2.1,
     'vBias': 0.5, 'gamma': 1.0})

# 4. MINOR TRIAD (10:12:15) — Muted deep tones
generate('04_minor_triad', 'Minor Triad — Muted Coral', 800, 500,
    [3, 6, 9, 12, 15, 18],
    [10, 11, 12, 13, 14, 15],
    {'mode': 'fbm', 'scale': 1.5, 'octaves': 2, 'lacunarity': 2.0,
     'gain': 0.3, 'offsetX': 4.4, 'offsetY': 8.1, 'gamma': 0.9})

# 5. MAJOR SEVENTH (8:10:12:15) — Soft luminous field
generate('05_major_seventh', 'Major 7th — Soft Field', 800, 500,
    [5, 7, 9, 11, 13, 15, 17, 19],
    [8, 9, 10, 11, 12, 13, 14, 15],
    {'mode': 'fbm', 'scale': 1.0, 'octaves': 1, 'lacunarity': 2.0,
     'gain': 0.3, 'offsetX': 2.2, 'offsetY': 5.5,
     'vBias': 0.3, 'gamma': 1.0})

# 6. DOMINANT SEVENTH (4:5:6:7) — Broad smooth blend
generate('06_dominant_seventh', 'Dominant 7th — Broad Blend', 800, 500,
    [4, 7, 9, 11, 14, 17, 19],
    [4, 4.5, 5, 5.5, 6, 6.5, 7],
    {'mode': 'fbm', 'scale': 1.8, 'octaves': 2, 'lacunarity': 2.0,
     'gain': 0.35, 'offsetX': 11.1, 'offsetY': 3.3, 'gamma': 1.0})

# 7. MINOR SEVENTH (10:12:15:18) — Quiet tonal shift
generate('07_minor_seventh', 'Minor 7th — Quiet Shift', 800, 500,
    [4, 6, 8, 10, 12, 14, 17, 19],
    [10, 11, 12, 13, 14, 15, 16.5, 18],
    {'mode': 'fbm', 'scale': 1.5, 'octaves': 2, 'lacunarity': 2.0,
     'gain': 0.3, 'offsetX': 6.6, 'offsetY': 9.9,
     'vBias': -0.2, 'gamma': 1.0})

# 8. DIMINISHED SEVENTH — Even, matte blend
generate('08_diminished_seventh', 'Dim7 — Matte Coral', 800, 500,
    [5, 8, 11, 15, 19],
    [1, 2**(3/12), 2**(6/12), 2**(9/12), 2],
    {'mode': 'fbm', 'scale': 1.2, 'octaves': 1, 'lacunarity': 2.0,
     'gain': 0.3, 'offsetX': 14.0, 'offsetY': 7.7, 'gamma': 1.0})

# 9. AUGMENTED TRIAD — Soft corner-to-corner
generate('09_augmented', 'Augmented — Soft Fade', 800, 500,
    [6, 9, 12, 16, 19],
    [1, 2**(3/12), 2**(6/12), 2**(9/12), 2],
    {'mode': 'fbm', 'scale': 1.0, 'octaves': 1, 'lacunarity': 2.0,
     'gain': 0.3, 'offsetX': 20.0, 'offsetY': 15.0, 'gamma': 1.0})

# 10. SUSPENDED FOURTH (6:8:9) — Gentle vertical gradient
generate('10_sus4', 'Sus4 — Gentle Gradient', 800, 400,
    [4, 6, 8, 10, 12, 15, 17, 19],
    [6, 6.4, 6.8, 7.3, 7.8, 8.3, 8.6, 9],
    {'mode': 'fbm', 'scale': 1.5, 'octaves': 2, 'lacunarity': 2.0,
     'gain': 0.3, 'offsetX': 3.3, 'offsetY': 1.1,
     'vBias': 0.6, 'gamma': 1.0})

# 11. MAJOR PENTATONIC — Warm even spread
generate('11_major_pentatonic', 'Major Pentatonic — Even Spread', 800, 500,
    [5, 7, 9, 11, 13, 15, 17, 19],
    [1, 9/8, 5/4, 11/8, 3/2, 5/3, 7/4, 2],
    {'mode': 'fbm', 'scale': 1.8, 'octaves': 2, 'lacunarity': 2.0,
     'gain': 0.3, 'offsetX': 8.8, 'offsetY': 4.4, 'gamma': 1.0})

# 12. WHOLE TONE — Ultra smooth, barely textured
wt = [2**(i/6) for i in range(7)]
generate('12_whole_tone', 'Whole Tone — Ultra Smooth', 800, 500,
    [6, 8, 10, 12, 15, 17, 20],
    wt,
    {'mode': 'fbm', 'scale': 1.0, 'octaves': 1, 'lacunarity': 2.0,
     'gain': 0.3, 'offsetX': 5.5, 'offsetY': 12.0, 'gamma': 1.0})

# 13. HARMONIC SERIES (partials 1-8) — Smooth wide sweep
generate('13_harmonic_series', 'Harmonic Series — Wide Sweep', 800, 600,
    [4, 6, 8, 10, 12, 14, 16, 18, 20],
    [1, 2, 3, 4, 5, 6, 7, 7.5, 8],
    {'mode': 'fbm', 'scale': 1.5, 'octaves': 2, 'lacunarity': 2.0,
     'gain': 0.3, 'offsetX': 17.0, 'offsetY': 22.0,
     'vBias': 0.25, 'gamma': 1.0})

# 14. MINOR PENTATONIC — Quiet muted field
generate('14_minor_pentatonic', 'Minor Pentatonic — Quiet Field', 800, 500,
    [3, 6, 9, 12, 15, 18],
    [1, 6/5, 4/3, 3/2, 9/5, 2],
    {'mode': 'fbm', 'scale': 1.5, 'octaves': 2, 'lacunarity': 2.0,
     'gain': 0.3, 'offsetX': 30.0, 'offsetY': 10.0,
     'vBias': -0.3, 'gamma': 0.95})

# 15. OVERTONE SCALE — Broad gentle field
generate('15_overtone_scale', 'Overtone Scale — Gentle Field', 900, 600,
    [4, 6, 8, 10, 11, 13, 15, 17, 19, 20],
    [1, 17/16, 9/8, 5/4, 11/8, 3/2, 13/8, 7/4, 15/8, 2],
    {'mode': 'fbm', 'scale': 1.8, 'octaves': 2, 'lacunarity': 2.0,
     'gain': 0.3, 'offsetX': 42.0, 'offsetY': 7.7,
     'vBias': 0.2, 'gamma': 1.0})

print('\nDone! Open gradients/*.html in a browser to view.')
